import java.io.*;
import java.util.*;

public class Main {
    static char[] digits;
    static long[][][] memo;

    static long count(int pos, int tight, int mask) {
        if (pos == digits.length) {
            return mask == 0 ? 0 : 1;
        }

        if (memo[pos][tight][mask] != -1) {
            return memo[pos][tight][mask];
        }

        int limit = tight == 1 ? digits[pos] - '0' : 9;
        long result = 0;

        for (int digit = 0; digit <= limit; digit++) {
            int nextTight = (tight == 1 && digit == limit) ? 1 : 0;
            int nextMask = mask;

            if (mask != 0 || digit != 0) {
                nextMask |= 1 << digit;
                if (Integer.bitCount(nextMask) > 2) {
                    continue;
                }
            }

            result += count(pos + 1, nextTight, nextMask);
        }

        return memo[pos][tight][mask] = result;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        digits = br.readLine().trim().toCharArray();

        memo = new long[digits.length + 1][2][1 << 10];
        for (long[][] layer : memo) {
            for (long[] row : layer) {
                Arrays.fill(row, -1);
            }
        }

        System.out.println(count(0, 1, 0));
    }
}

