import java.io.*;
import java.util.*;

public class Main {
    static char[] digits;
    static long[][][][] memo;

    static long count(int pos, int tight, int started, int mask) {
        if (Integer.bitCount(mask) > 2) return 0;
        if (pos == digits.length) return started == 1 ? 1 : 0;

        if (memo[pos][tight][started][mask] != -1) {
            return memo[pos][tight][started][mask];
        }

        int limit = tight == 1 ? digits[pos] - '0' : 9;
        long result = 0;

        for (int digit = 0; digit <= limit; digit++) {
            int nextTight = (tight == 1 && digit == limit) ? 1 : 0;

            if (started == 0 && digit == 0) {
                result += count(pos + 1, nextTight, 0, mask);
            } else {
                int nextMask = mask | (1 << digit);
                if (Integer.bitCount(nextMask) <= 2) {
                    result += count(pos + 1, nextTight, 1, nextMask);
                }
            }
        }

        return memo[pos][tight][started][mask] = result;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        digits = reader.readLine().trim().toCharArray();

        memo = new long[digits.length][2][2][1 << 10];
        for (long[][][] a : memo) {
            for (long[][] b : a) {
                for (long[] c : b) {
                    Arrays.fill(c, -1);
                }
            }
        }

        System.out.println(count(0, 1, 0, 0));
    }
}

